begin;
select plan(23);
\ir helpers/private_beta_uat_fixtures.sql
select pg_temp.beta_setup(911);
select pg_temp.beta_setup(912);
select pg_temp.beta_auth(911);
do $$declare i integer;begin for i in 1..251 loop perform public.admin_private_beta_note_v1(pg_temp.beta_id(911,'2000'),pg_temp.beta_id(911,'3000'),null,'MULTITURN_CONTEXT','NOTE','Synthetic note '||i,pg_temp.beta_id(i,'7000'));end loop;end;$$;
create temp table beta_pages(k text primary key,v jsonb);
insert into beta_pages values('first',public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000')));
select is(jsonb_array_length((select v->'items'from beta_pages where k='first')),25,'notes default25 is independently bounded');
select is((select v->>'has_more'from beta_pages where k='first'),'true','large notes history remains explicitly incomplete');
select ok((select v->'next_cursor'->>'seal'~'^[a-f0-9]{64}$'from beta_pages where k='first'),'cursor is cryptographically sealed at SQL source');
select is(jsonb_array_length(public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),100)->'items'),100,'hard maximum100 does not truncate all historical access');
select throws_ok($q$select public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),101)$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','oversized notes page request denied');
select is(jsonb_array_length(public.admin_private_beta_workspace_v1(pg_temp.beta_id(911,'2000'))->'notes'),25,'workspace notes preview bounded separately from attempts');
select is(public.admin_private_beta_workspace_v1(pg_temp.beta_id(911,'2000'))->>'notes_has_more','true','workspace exposes the need for historical notes page');
select throws_ok($q$select public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),25,(select jsonb_set(v->'next_cursor','{expires}',to_jsonb((clock_timestamp()+interval '29 minutes')::text))from beta_pages where k='first'))$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','changing TTL without SQL seal fails closed');
select throws_ok($q$select public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),25,(select jsonb_set(v->'next_cursor','{anchor,id}',to_jsonb(pg_temp.beta_id(911,'7000')::text))from beta_pages where k='first'))$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','anchor tampering invalidates cursor seal');
select throws_ok($q$select public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),10,(select v->'next_cursor'from beta_pages where k='first'))$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','cursor cannot cross page-size scope');
select throws_ok($q$select public.admin_private_beta_workspace_v1(pg_temp.beta_id(911,'2000'),25,(select v->'next_cursor'from beta_pages where k='first'))$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','notes cursor cannot cross into attempt collection');
select pg_temp.beta_auth(911,'support');
select throws_ok($q$select public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),25,(select v->'next_cursor'from beta_pages where k='first'))$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','cursor is bound to exact operator and role');
select pg_temp.beta_auth(912);
select throws_ok($q$select public.admin_private_beta_notes_page_v1(pg_temp.beta_id(912,'2000'),25,(select v->'next_cursor'from beta_pages where k='first'))$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','cursor cannot cross tenant/program boundaries');
select pg_temp.beta_auth(911);
create temp table traversed_notes(id uuid primary key);
do $$declare page jsonb;cur jsonb;i integer;begin
 for i in 1..20 loop page:=public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),25,cur);insert into traversed_notes select(value->>'id')::uuid from jsonb_array_elements(page->'items');exit when not(page->>'has_more')::boolean;cur:=page->'next_cursor';end loop;
 if(page->>'has_more')::boolean then raise exception 'bounded fixture traversal did not finish';end if;
end;$$;
select is((select count(*)from traversed_notes),251::bigint,'all251 historical notes remain accessible with no duplicated key');
select is((select count(*)from private.private_beta_observations o left join traversed_notes n using(id)where o.program_id=pg_temp.beta_id(911,'3000')and n.id is null),0::bigint,'pagination silently loses no historical notes');
select public.admin_private_beta_note_v1(pg_temp.beta_id(911,'2000'),pg_temp.beta_id(911,'3000'),null,'MULTITURN_CONTEXT','NOTE','Later synthetic note',pg_temp.beta_id(999,'7000'));
select ok(not exists(select 1 from jsonb_array_elements(public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),25,(select v->'next_cursor'from beta_pages where k='first'))->'items')v where v->>'note'='Later synthetic note'),'anchor fences concurrent inserted note until refresh');
select is((select count(*)from private.private_beta_observations where program_id=pg_temp.beta_id(911,'3000')),252::bigint,'newly appended note is retained for refresh');
select public.admin_private_beta_note_v1(pg_temp.beta_id(911,'2000'),pg_temp.beta_id(911,'3000'),null,'MULTITURN_CONTEXT','NOTE','Later synthetic note',pg_temp.beta_id(999,'7000'));
select is((select count(*)from private.private_beta_observations where program_id=pg_temp.beta_id(911,'3000')),252::bigint,'identical note command replay appends once');
select throws_ok($q$select public.admin_private_beta_note_v1(pg_temp.beta_id(911,'2000'),pg_temp.beta_id(911,'3000'),null,'MULTITURN_CONTEXT','NOTE','Conflicting note',pg_temp.beta_id(999,'7000'))$q$,'22023','PRIVATE_BETA_INVALID','conflicting command does not rewrite observation');
select throws_ok($q$update private.private_beta_observations set note='changed'where program_id=pg_temp.beta_id(911,'3000')$q$,'42501','FSE_IMMUTABLE','review evidence remains append-only');
select is((select v->'items'->0->>'author'from beta_pages where k='first'),'OPERATOR','operator authorship is clear without exposing private identity');
update private.private_beta_programs set generation=generation+1 where id=pg_temp.beta_id(911,'3000');
select throws_ok($q$select public.admin_private_beta_notes_page_v1(pg_temp.beta_id(911,'2000'),25,(select v->'next_cursor'from beta_pages where k='first'))$q$,'22023','PRIVATE_BETA_CURSOR_INVALID','program generation drift requires refresh');
select ok(not has_function_privilege('service_role','public.admin_private_beta_notes_page_v1(uuid,integer,jsonb)','execute'),'machine runtime cannot scrape private operator notes through Admin wrapper');
select * from finish();
rollback;
